		{ x: 5903, y: 465, cx: 5908, cy: 470 },
		{ x: 5768, y: 470, cx: 5773, cy: 475 },
		{ x: 5908, y: 430, cx: 5913, cy: 435 },
		{ x: 5908, y: 410, cx: 5913, cy: 415 },
		{ x: 5908, y: 390, cx: 5913, cy: 395 }
	];
	let scales = new Array(dots.length).fill(1);

	/** @param {MouseEvent | TouchEvent} e */
	function onMove(e) {
		const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
		const y = 'touches' in e ? e.touches[0].clientY : e.clientY;
		const svg = document.querySelector('svg');
		if (!svg) return;
		const rect = svg.getBoundingClientRect();
		const svgW = rect.width;
		const svgH = rect.height;
		const sx = 6048 / svgW;
		const sy = 3928 / svgH;
		mx = (x - rect.left) * sx;
		my = (y - rect.top) * sy;
		if (!raf) raf = requestAnimationFrame(tick);
	}

	function onLeave() {
		mx = -10000;
		my = -10000;
		if (!raf) raf = requestAnimationFrame(tick);
	}

	function onResize() {}

	function tick() {
		raf = 0;
		const r2 = RADIUS * RADIUS;
		for (let i = 0; i < dots.length; i++) {
			const d = dots[i];
			const dx = d.cx - mx;
			const dy = d.cy - my;
			const dist2 = dx * dx + dy * dy;
			let s = 1;
			if (dist2 < r2) {
				const dist = Math.sqrt(dist2);
				const t = 1 - dist / RADIUS;
				s = 1 + t * (MAX_SCALE - 1);
			}
			if (s !== scales[i]) {
				scales[i] = s;
				const el = document.getElementById('d' + i);
				if (el)
					el.setAttribute(
						'transform',
						s === 1
							? ''
							: 'translate(' + (d.cx - d.x * s) + ',' + (d.cy - d.y * s) + ') scale(' + s + ')'
					);
			}
		}
	}

	import { onMount } from 'svelte';
	onMount(() => {
		window.addEventListener('mousemove', onMove);
		window.addEventListener('mouseleave', onLeave);
		window.addEventListener('touchmove', onMove, { passive: true });
		window.addEventListener('touchend', onLeave);
		window.addEventListener('touchcancel', onLeave);
		window.addEventListener('resize', onResize);
		return () => {
			window.removeEventListener('mousemove', onMove);
			window.removeEventListener('mouseleave', onLeave);
			window.removeEventListener('touchmove', onMove);
			window.removeEventListener('touchend', onLeave);
			window.removeEventListener('touchcancel', onLeave);
			window.removeEventListener('resize', onResize);
		};
	});
</script>

